// [T-image-repro] Scenario runner. Drives the extracted production code (see
// Extracted.swift, generated by ImagePipelineReproTests.swift) and prints one
// `R key=<json>` line per measurement for the driver to assert on.
import Foundation
import UIKit
import UniformTypeIdentifiers
import SwiftAnthropic
import CryptoKit

setvbuf(stdout, nil, _IOLBF, 0)
if CommandLine.arguments.count > 1 { HarnessEnv.root = URL(fileURLWithPath: CommandLine.arguments[1]) }
let fm = FileManager.default
try? fm.removeItem(at: HarnessEnv.root)
try? fm.createDirectory(at: HarnessEnv.root, withIntermediateDirectories: true)
let sid = HarnessEnv.sessionId
let vm = AIChatViewModel()

func R(_ key: String, _ value: Any) {
    let data = try! JSONSerialization.data(withJSONObject: value, options: [.fragmentsAllowed])
    print("R \(key)=\(String(data: data, encoding: .utf8)!)")
}
/// Dimensions / format / declared MIME / bytes of one image.
func record(_ key: String, _ data: Data, mime: String? = nil) {
    let p = probe(data)
    R(key + ".w", p.w); R(key + ".h", p.h); R(key + ".bytes", data.count); R(key + ".fmt", p.fmt)
    R(key + ".alpha", p.alpha); R(key + ".corner", p.corner)
    if let mime { R(key + ".mime", mime) }
}
func write(_ data: Data, _ name: String) -> URL {
    let dir = HarnessEnv.root.appendingPathComponent("Caches/InputAttachments")
    try? fm.createDirectory(at: dir, withIntermediateDirectories: true)
    let url = dir.appendingPathComponent(name)
    try! data.write(to: url)
    return url
}

// MARK: - Persist → reload (the path loadSession takes)

/// Encode parts the way the DB stores them (parts_json) and rebuild with the
/// real `RawMessage.toAgentMessage` and the real media resolver.
func reload(_ rows: [(MessageRole, [ContentPart])]) async -> [AgentMessage] {
    let resolver = await ChatStore.shared.mediaFileURLResolver()
    return rows.enumerated().map { i, row in
        let json = try! JSONEncoder().encode(row.1)
        let parts = try! JSONDecoder().decode([ContentPart].self, from: json)
        let raw = RawMessage(id: "m\(i)", sessionId: sid, role: row.0, parts: parts, createdAt: Date())
        return raw.toAgentMessage(mediaResolver: resolver)
    }
}
func toolImage(_ h: [AgentMessage]) -> (data: Data, mime: String)? {
    for m in h { for p in m.parts { if case .toolResult(_, _, _, _, let d?, let mime, _, _, _) = p { return (d, mime ?? "nil") } } }
    return nil
}
func userImage(_ h: [AgentMessage]) -> (data: Data, mime: String)? {
    for m in h { for p in m.parts { if case .imageData(let d, let mime, _) = p { return (d, mime) } } }
    return nil
}
func subdirOf(_ ref: MediaRef) -> String { ref.relativePath.split(separator: "/").dropFirst().first.map(String.init) ?? "?" }
func fileData(_ ref: MediaRef) async -> Data? {
    let url = await ChatStore.shared.mediaFileURLResolver()(ref)
    return try? Data(contentsOf: url)
}

// MARK: - Every provider serializer

let visionModel = LLMModel(id: "gpt-repro", displayName: "repro", provider: "openai", modalityOverride: .vision)
let geminiModel = LLMModel(id: "gemini-2.5-pro", displayName: "repro", provider: "gemini", modalityOverride: .vision)
let claudeModel = LLMModel(id: "claude-sonnet-5", displayName: "repro", provider: "anthropic", modalityOverride: .vision)

/// Runs `applyRequestImageBudget` (as every agent request does), then each
/// serializer, and records each request's images.
func wire(_ history: [AgentMessage], _ key: String) {
    let budgeted = vm.applyRequestImageBudget(history)
    var bodies: [(String, Any, String)] = []
    let responses = OpenAIAgentProvider(model: visionModel).convertMessagesResponsesAPI(budgeted)
    bodies.append(("responses", responses, orderSignature(responses)))
    let chat = OpenAIAgentProvider(model: visionModel).flattenChatCompletionsMessages(budgeted)
    bodies.append(("chat", chat, orderSignature(chat)))
    let gemini = GeminiAgentProvider(model: geminiModel).convertMessages(budgeted)
    bodies.append(("gemini", gemini, ""))
    let ag = AntigravityAgentProvider(model: geminiModel).convertMessages(budgeted)
    bodies.append(("antigravity", ag, ""))
    // Anthropic: SDK request model → JSON body → RequestBodyPatcher (tool images).
    let ap = AnthropicAgentProvider(model: claudeModel)
    let msgs = ap.harnessConvert(budgeted)
    let param = MessageParameter(model: .other("claude-sonnet-5"), messages: msgs, maxTokens: 64)
    let req = NSMutableURLRequest(url: URL(string: "https://api.anthropic.com/v1/messages")!)
    // Same encoder settings as SwiftAnthropic's Endpoint.swift (snake_case keys).
    let encoder = JSONEncoder()
    encoder.keyEncodingStrategy = .convertToSnakeCase
    req.httpBody = try! encoder.encode(param)
    let token = UUID().uuidString
    req.setValue(token, forHTTPHeaderField: RequestBodyPatcher.requestTokenHeader)
    RequestBodyPatcher.setToolResultImages(ap.harnessPendingToolResultImages, requestToken: token)
    RequestBodyPatcher.patchToolResultsWithImages(into: req)
    let anthropicJSON = try! JSONSerialization.jsonObject(with: req.httpBody!)
    bodies.append(("anthropic", anthropicJSON, ""))

    for (name, body, order) in bodies {
        let imgs = wireImages(body)
        R("\(key).\(name).count", imgs.count)
        if !order.isEmpty { R("\(key).\(name).order", order) }
        if let first = imgs.first {
            record("\(key).\(name)", first.data, mime: first.mime)
            if key.contains("exif6") { R("\(key).\(name).orientation", orientationVerdict(first.data)) }
            R("\(key).\(name).sha", SHA256.hash(data: first.data).prefix(8).map { String(format: "%02x", $0) }.joined())
            R("\(key).\(name).b64", first.b64Length)
            R("\(key).\(name).over8192", max(probe(first.data).w, probe(first.data).h) > 8192)
            R("\(key).\(name).over2000", max(probe(first.data).w, probe(first.data).h) > 2000)
            R("\(key).\(name).over3_5MB", first.data.count > 3_500_000)
        }
    }
}

// MARK: - Tool-result scenarios (browser_use, read_image)

func toolHistory(id: String, name: String, image: Data?, mime: String?, linuxPath: String?) -> [AgentMessage] {
    [AgentMessage(role: .user, parts: [.text("look at it")]),
     AgentMessage(role: .assistant, parts: [.toolUse(id: id, name: name, input: ["action": "screenshot"])]),
     AgentMessage(role: .user, parts: [.toolResult(id: id, name: name, content: "Screenshot captured", isError: false,
                                                    imageData: image, imageMimeType: mime, imageLinuxPath: linuxPath)]),
     AgentMessage(role: .user, parts: [.text("next question")])]
}
func toolRows(id: String, name: String, ref: MediaRef?) -> [(MessageRole, [ContentPart])] {
    [(.user, [.text("look at it")]),
     (.assistant, [.toolUse(ToolUse(toolUseId: id, name: name, input: "{\"action\":\"screenshot\"}", description: nil, thoughtSignature: nil))]),
     (.user, [.toolResult(ToolResult(toolUseId: id, output: "Screenshot captured", success: true, mediaRef: ref,
                                     snapshot: nil, pageURL: nil, status: "success"))]),
     (.user, [.text("next question")])]
}

/// browser_use: screenshot → live bytes → B2/B3 copies → persisted ref → reload → wire.
func browserScenario(_ key: String, pointW: Int, pointH: Int) async {
    let shot = screenshotLike(pointW: pointW, pointH: pointH)
    record("\(key).src", shot.data, mime: "image/jpeg")
    R("\(key).reportedSize", "\(Int(shot.size.width))x\(Int(shot.size.height))")
    R("\(key).metaLine", "  Image: \(Int(shot.size.width))x\(Int(shot.size.height)) (\(shot.data.count / 1024)KB)")
    // B1: BrowserUseManager writes the JPEG to tmp/browser_screenshots.
    let b1 = HarnessEnv.root.appendingPathComponent("tmp/browser_screenshots/screenshot_1.jpg")
    try? fm.createDirectory(at: b1.deletingLastPathComponent(), withIntermediateDirectories: true)
    try! shot.data.write(to: b1)
    let live = vm.browserUseLive(data: shot.data)
    record("\(key).live", live.data, mime: live.mime)
    // B3: the snapshot saveMedia reads the block's imageFilePath (= B1).
    let ref = await vm.persistBrowserSnapshot(imageData: try! Data(contentsOf: b1), sid: sid, toolImageLinuxPath: nil)
    let persisted = await fileData(ref)!
    record("\(key).persisted", persisted, mime: ref.mimeType)
    R("\(key).persisted.subdir", subdirOf(ref))
    let b2 = (try? Data(contentsOf: live.b2)) ?? Data()
    R("\(key).copies.original", [shot.data, persisted, b2].filter { $0 == shot.data }.count)
    let liveHistory = toolHistory(id: "call_\(key)|fc_\(key)", name: "browser_use", image: live.data, mime: live.mime, linuxPath: nil)
    let mediaRef = vm.persistedToolResultRef(imgData: live.data, snapshotRef: ref)
    let rebuilt = await reload(toolRows(id: "call_\(key)|fc_\(key)", name: "browser_use", ref: mediaRef))
    if let r = toolImage(rebuilt) { record("\(key).rebuilt", r.data, mime: r.mime); R("\(key).liveEqualsRebuilt", r.data == live.data) }
    else { R("\(key).rebuilt.w", 0); R("\(key).liveEqualsRebuilt", false) }
    wire(liveHistory, "\(key).wire.live")
    wire(rebuilt, "\(key).wire.rebuilt")
}

/// read_image: file → live bytes → R1 copy → persisted ref → reload → wire.
func readImageScenario(_ key: String, file: URL) async {
    let data = try! Data(contentsOf: file)
    record("\(key).src", data)
    let live = vm.readImageLive(fileData: data, uiImage: UIImage(data: data)!)
    record("\(key).live", live.data, mime: live.mime)
    let ref = await vm.persistReadImageSnapshot(imagePath: file.path, imageData: try! Data(contentsOf: file), sid: sid,
                                                toolImageLinuxPath: "/var/minis/attachments/uploads/\(file.lastPathComponent)")
    let persisted = await fileData(ref)!
    record("\(key).persisted", persisted, mime: ref.mimeType)
    R("\(key).persisted.subdir", subdirOf(ref))
    R("\(key).persisted.declaredMime", ref.mimeType)
    R("\(key).persisted.ext", (ref.relativePath as NSString).pathExtension)
    let id = "call_\(key)|fc_\(key)"
    let mediaRef = vm.persistedToolResultRef(imgData: live.data, snapshotRef: ref)
    let rebuilt = await reload(toolRows(id: id, name: "read_image", ref: mediaRef))
    if let r = toolImage(rebuilt) { record("\(key).rebuilt", r.data, mime: r.mime); R("\(key).liveEqualsRebuilt", r.data == live.data) }
    wire(toolHistory(id: id, name: "read_image", image: live.data, mime: live.mime, linuxPath: nil), "\(key).wire.live")
    wire(rebuilt, "\(key).wire.rebuilt")
}

// MARK: - Attachment scenarios (send path, queue path)

func attachmentRows(_ text: String, _ ref: MediaRef) -> [(MessageRole, [ContentPart])] {
    [(.user, [.text(text), .mediaRef(ref)])]
}
/// Send path (verbatim block from send()) + persistence + reload.
func sendScenario(_ key: String, file: URL, wireIt: Bool = false) async -> Data? {
    let data = try! Data(contentsOf: file)
    let att = InputAttachment(fileName: file.lastPathComponent, cacheURL: file, kind: .image)
    let linuxPath = "/var/minis/attachments/uploads/\(file.lastPathComponent)"
    let parts = await vm.sendPathImage(att, data: data, linuxPath: linuxPath)
    R("\(key).imageParts", parts.filter { if case .imageData = $0 { return true }; return false }.count)
    R("\(key).hasAttachedMarker", parts.contains { if case .text(let t) = $0 { return t.hasPrefix("[attached image:") }; return false })
    guard let (img, mime) = userImage([AgentMessage(role: .user, parts: parts)]) else { R("\(key).live.w", 0); return nil }
    record("\(key).live", img, mime: mime)
    let ref = await vm.persistedImagePart(data: img, mimeType: mime, sessionId: sid, linuxPath: linuxPath)
    R("\(key).persisted.subdir", subdirOf(ref))
    let rebuilt = await reload(attachmentRows("see attached", ref))
    if let r = userImage(rebuilt) {
        record("\(key).rebuilt", r.data, mime: r.mime)
        R("\(key).liveEqualsRebuilt", r.data == img)
    }
    if wireIt {
        wire(rebuilt + [AgentMessage(role: .user, parts: [.text("next")])], "\(key.replacingOccurrences(of: ".send", with: "")).wire.rebuilt")
    }
    return img
}
/// Queue-drain path: the real processAttachments.
func queueScenario(_ key: String, file: URL, wireKey: String? = nil) async -> Data? {
    let uploads = HarnessEnv.root.appendingPathComponent("MinisChat/minis/\(sid)/attachments/uploads")
    try? fm.createDirectory(at: uploads, withIntermediateDirectories: true)
    let att = InputAttachment(fileName: file.lastPathComponent, cacheURL: file, kind: .image)
    let (parts, _) = vm.processAttachments([att], uploadsDir: uploads, nowStr: "2026-10-04T00:00:00Z")
    guard let (img, mime) = userImage([AgentMessage(role: .user, parts: parts)]) else { R("\(key).w", 0); return nil }
    record(key, img, mime: mime)
    let ref = await vm.persistedImagePart(data: img, mimeType: mime, sessionId: sid, linuxPath: nil)
    let rebuilt = await reload(attachmentRows("queued", ref))
    if let r = userImage(rebuilt) { R("\(key.replacingOccurrences(of: ".live", with: "")).liveEqualsRebuilt", r.data == img) }
    if let wireKey { wire(rebuilt + [AgentMessage(role: .user, parts: [.text("next")])], wireKey) }
    return img
}

// MARK: - Run

func run() async {
    // S1 / S2: browser screenshots
    await browserScenario("s1", pointW: 920, pointH: 7297)
    await browserScenario("s2a", pointW: 390, pointH: 844)
    await browserScenario("s2b", pointW: 3000, pointH: 2000)

    // S3: camera — downsampledCameraJPEG on a full-size capture
    let capture = UIImage(cgImage: makeCGImage(w: 4032, h: 3024, pattern: .photo))
    let c1 = AIChatViewModel.downsampledCameraJPEG(capture)!
    record("s3.c1", c1, mime: "image/jpeg")
    let c1url = write(c1, "camera.jpg")
    record("s3.c2", c1)   // uploads/ copy is a byte-for-byte copyItem of C1 (send() / processAttachments)
    _ = await sendScenario("s3.send", file: c1url, wireIt: true)
    _ = await queueScenario("s3.queue.live", file: c1url)

    // S4: photo-library picks
    let jpeg = encode(makeCGImage(w: 4032, h: 3024, pattern: .photo), type: .jpeg, quality: 0.9)
    let jpegURL = write(jpeg, "IMG_0001.jpg")
    _ = await sendScenario("s4.jpeg.send", file: jpegURL)
    let heic = encode(makeCGImage(w: 4032, h: 3024, pattern: .photo), type: .heic, quality: 0.8)
    let heicURL = write(heic, "IMG_0002.heic")
    record("s4.heic.src", heic)
    _ = await sendScenario("s4.heic.send", file: heicURL)
    let heicSmall = encode(makeCGImage(w: 1200, h: 900, pattern: .photo), type: .heic, quality: 0.8)
    let heicSmallURL = write(heicSmall, "IMG_0003.heic")
    _ = await sendScenario("s4.heicSmall.send", file: heicSmallURL, wireIt: true)
    let exif6 = encode(makeCGImage(w: 4032, h: 3024, pattern: .photo), type: .jpeg, quality: 0.9, orientation: 6)
    _ = await sendScenario("s4.exif6.send", file: write(exif6, "IMG_0004.jpg"))
    let png = encode(makeCGImage(w: 512, h: 512, pattern: .flat, alpha: true), type: .png)
    _ = await sendScenario("s4.png.send", file: write(png, "logo.png"))
    let pngBig = encode(makeCGImage(w: 3000, h: 3000, pattern: .flat, alpha: true), type: .png)
    _ = await sendScenario("s4.pngBig.send", file: write(pngBig, "big.png"))

    // S5: read_image
    let page = screenshotLike(pointW: 920, pointH: 7297).data
    let pageURL = write(page, "page.jpg")
    await readImageScenario("s5.big", file: pageURL)
    await readImageScenario("s5.heic", file: heicURL)
    // EXIF orientation 6 photo read with read_image, then reloaded
    let exif6Halves = encode(makeCGImage(w: 4032, h: 3024, pattern: .halves), type: .jpeg, quality: 0.9, orientation: 6)
    await readImageScenario("s5.exif6", file: write(exif6Halves, "IMG_0005.jpg"))
    R("s5.exif6.live.orientation", orientationVerdict(vm.readImageLive(fileData: exif6Halves, uiImage: UIImage(data: exif6Halves)!).data))
    R("s5.exif6.jpegEncode.orientation", orientationVerdict(AIChatViewModel.jpegEncode(exif6Halves, maxLongEdge: 2000, quality: 0.85)!))
    // same image twice
    let imagesDir = HarnessEnv.root.appendingPathComponent("MinisChat/minis/\(sid)/images")
    try? fm.removeItem(at: imagesDir)
    let small = encode(makeCGImage(w: 1600, h: 1200, pattern: .photo), type: .jpeg, quality: 0.9)
    let smallURL = write(small, "small.jpg")
    let a = vm.readImageLive(fileData: small, uiImage: UIImage(data: small)!)
    let b = vm.readImageLive(fileData: small, uiImage: UIImage(data: small)!)
    _ = await vm.persistReadImageSnapshot(imagePath: smallURL.path, imageData: small, sid: sid, toolImageLinuxPath: nil)
    _ = await vm.persistReadImageSnapshot(imagePath: smallURL.path, imageData: small, sid: sid, toolImageLinuxPath: nil)
    R("s5.twice.r1Copies", (try? fm.contentsOfDirectory(atPath: imagesDir.path).count) ?? 0)
    R("s5.twice.liveSame", a.data == b.data)

    // S6: queue vs send
    let s6send = await sendScenario("s6.jpeg.sendRaw", file: jpegURL)
    let s6queue = await queueScenario("s6.jpeg.queueRaw.live", file: jpegURL)
    if let s6send { record("s6.jpeg.send", s6send) }
    if let s6queue { record("s6.jpeg.queue", s6queue) }
    R("s6.jpeg.identical", s6send == s6queue)
    let gif = encode(makeCGImage(w: 2400, h: 1800, pattern: .photo), type: .gif)
    let gifURL = write(gif, "anim.gif")
    _ = await queueScenario("s6.gif.queue.live", file: gifURL, wireKey: "s6.gif.wire.rebuilt")
    _ = await sendScenario("s6.gif.sendRaw", file: gifURL)
    // <=2000 so resizedImageData passes it through untouched; q1.0 noise makes
    // it big enough (> the ladder's raw target) for the ladder to matter.
    let noisy = encode(makeCGImage(w: 2000, h: 2000, pattern: .noise), type: .jpeg, quality: 1.0)
    record("s6.noisy.src", noisy)
    let noisyURL = write(noisy, "noisy.jpg")
    let ns = await sendScenario("s6.noisy.sendRaw", file: noisyURL)
    let nq = await queueScenario("s6.noisy.queueRaw.live", file: noisyURL)
    R("s6.noisy.send.bytes", ns?.count ?? -1)
    R("s6.noisy.queue.bytes", nq?.count ?? -1)
    let ladderTarget = AIChatViewModel.rawBytesForBase64Budget(AIChatViewModel.kPerImageMaxBytes)
    R("s6.noisy.ladderTargetRaw", ladderTarget)
    R("s6.noisy.queueHasNoLadder", (nq?.count ?? 0) > ladderTarget && (ns?.count ?? Int.max) <= ladderTarget)

    // P-i4 takeover: raw screenshot appended as-is
    let bigShot = screenshotLike(pointW: 3000, pointH: 2000).data
    let msg = vm.takeoverMessage(data: bigShot, linuxPath: "/var/minis/browser/takeover_1.jpg")
    if let (d, mime) = userImage([msg]) { record("p4.live", d, mime: mime) }
    wire([AgentMessage(role: .user, parts: [.text("take over")]), msg], "p4.wire.live")

    // P-i6 re-encoding stability
    let once = AIChatViewModel.jpegEncode(page, maxLongEdge: 2000, quality: 0.85)!
    let twice = AIChatViewModel.jpegEncode(once, maxLongEdge: 2000, quality: 0.85)!
    R("p6.once", once.count); R("p6.twice", twice.count)
    R("p6.jpegEncodeIdempotent", once == twice)
    R("p6.resizedPassThrough", AIChatViewModel.resizedImageData(once, maxLongEdge: 2000) == nil)
    R("p6.readImageChangesBytes", a.data != small)

    // P-i8 request budget is bytes-only
    let strip = encode(makeCGImage(w: 9000, h: 300, pattern: .flat), type: .jpeg, quality: 0.5)
    record("p8.src", strip)
    let h8 = [AgentMessage(role: .user, parts: [.text("strip"), .imageData(data: strip, mimeType: "image/jpeg", linuxPath: nil)])]
    let b8 = vm.applyRequestImageBudget(h8)
    R("p8.untouched", userImage(b8)?.data == strip)
    wire(h8, "p8.wire")

    // Missing media on reload: the mediaRef file is gone
    let ghost = MediaRef(id: "ghost", relativePath: "\(sid)/attachments/ghost.jpg", mimeType: "image/jpeg", originalFileName: nil)
    let missing = await reload([(.user, [.text("where is it"), .mediaRef(ghost)])])
    R("miss.parts", missing[0].parts.map { p -> String in
        switch p { case .text: return "text"; case .imageData: return "image"; default: return "other" }
    }.joined(separator: ","))
}

// Top-level await keeps the main actor free: the send path hops to it
// (`await MainActor.run { … }`), so blocking main here would deadlock.
await run()
